def hero(t):
  chips="".join(f'<button data-chip="{i}" class="{t["chip"]}">{c[0]}</button>' for i,c in enumerate(CHIPS))
  return f'''<div class="{t["box"]}"><label class="block text-lg md:text-2xl font-bold mb-3">Mit szeretnél megkérdezni Magyarországtól?</label><div class="flex flex-col md:flex-row gap-3"><input id="q" class="{t["inp"]}" placeholder="Pl. megvennék-e a termékemet 4 990 Ft-ért?"><a id="go" href="#" class="{t["btn"]} text-center whitespace-nowrap">Kutatás indítása →</a></div>
<div class="flex flex-wrap gap-2 mt-3">{chips}</div><div class="flex flex-wrap items-center gap-3 mt-4 text-sm"><span class="{t["badge"]}">már 9 900 Ft-tól <small class="opacity-70">(példa ár)</small></span><span class="opacity-70">Eredmény perceken–órákon belül · 3000 szintetikus avatar · szimulált panel, nem reprezentatív felmérés</span></div></div>
<div id="res" class="hidden transition-opacity duration-700 mt-4 {t["card"]}"><div class="flex justify-between flex-wrap gap-2 items-center"><div><p class="text-xs opacity-60">Mintaeredmény</p><p id="rq" class="font-bold"></p></div><span class="text-xs font-mono" id="rs"></span>{MD}</div>
<div class="grid md:grid-cols-3 gap-4 mt-3"><div><canvas id="rc"></canvas></div><div><canvas id="rc2"></canvas></div><div><p class="text-xs opacity-70 mb-1">Leggyakoribb indoklások</p><div id="rw"></div><p class="text-[11px] opacity-60 mt-3">Illusztráció: a valódi riport szegmenseket, idézeteket és javaslatokat is tartalmaz.</p></div></div></div>'''
TIERS=[("Gyorskérdés","9 900 Ft","1 kérdés, 3000 avatar, összefoglaló + 3 grafikon, percek alatt"),("Piackutatás","49 000 Ft","Termék/ár/szlogen teszt, szegmensek, árérzékenység, javaslatok"),("Közvélemény-kutatás","79 000 Ft","Társadalmi/közéleti kérdés, régiós és demográfiai bontás"),("Trendfigyelő előfizetés","29 000 Ft / hó","Heti hírreakció- és trendjelentés a te témáidra"),("Weboldal + kutatás","egyedi","A kutatásra épülő, értékesítő weboldal kulcsrakészen")]
def tiers(card,acc): return '<div class="grid md:grid-cols-3 lg:grid-cols-5 gap-4">'+"".join(f'<div class="{card} flex flex-col {"ring-2 ring-current" if i==1 else ""}"><span class="text-[10px] self-start px-1.5 py-0.5 rounded bg-amber-400/25 text-amber-600 font-semibold">példa ár</span><h3 class="font-bold mt-2">{a}</h3><div class="text-2xl font-bold {acc} mt-1">{p}</div><p class="text-sm opacity-80 mt-2 flex-1">{d}</p><a href="#top" class="mt-4 text-sm font-semibold underline">Kipróbálom →</a></div>' for i,(a,p,d) in enumerate(TIERS))+'</div>'
USE=[("Kisvállalkozás","bolt","Új termék, ár vagy akció kipróbálása, mielőtt legyártod."),("Ügynökség","iroda","Kampány-előteszt és szlogen A/B gyorsan, ügyfélnek bemutatható riporttal."),("Rendezvényszervező","szentendre","Jegyár, helyszín, fellépő: kire mennének el és mennyiért?"),("Politika / önkormányzat","kecskemet","Közéleti kérdések, helyi fejlesztések fogadtatása — szimulált hangulatkép."),("Startup","westend","Piac-validálás és célcsoport-keresés napok helyett percek alatt.")]
def uses(card): return '<div class="grid md:grid-cols-5 gap-4">'+"".join(f'<div class="{card} !p-0 overflow-hidden"><div class="h-32">{img(k)}</div><div class="p-4"><h3 class="font-bold">{a}</h3><p class="text-sm opacity-80 mt-1">{d}</p></div></div>' for a,k,d in USE)+'</div>'
LIM='<div class="grid md:grid-cols-2 gap-6"><div><h3 class="font-bold text-lg">Hogyan működik a panel?</h3><ul class="mt-2 space-y-2 text-sm opacity-90 list-disc pl-5"><li>3000 szintetikus avatar, életkor, nem, régió, településtípus, végzettség és jövedelem szerint a KSH-arányokhoz igazítva.</li><li>Minden avatar MI-modellel „gondolkodik”: válaszol, indokol, vitatkozik.</li><li>Az eredményt szegmensekre bontjuk és grafikonokkal, javaslatokkal adjuk át.</li></ul></div><div><h3 class="font-bold text-lg">Őszintén a korlátokról</h3><ul class="mt-2 space-y-2 text-sm opacity-90 list-disc pl-5"><li>Ez gyors, olcsó <b>szimulált panel</b>, nem valós emberek reprezentatív felmérése.</li><li>Az avatarok nem valós, megnevezett személyek, személyes adatot nem használunk.</li><li>Irány- és ötletteszteléshez ideális; nagy téttel járó döntés előtt valós mintás kontrollkutatást javaslunk.</li><li>Az MI-modellek torzításokat hordozhatnak — ezért mindig jelezzük a bizonytalanságot.</li></ul></div></div>'
FAQ2=[("Valós emberektől származnak a válaszok?","Nem. 3000 szintetikus, MI-alapú avatar válaszol, a magyar népesség arányait követve. Gyors és olcsó, de nem helyettesíti a reprezentatív felmérést."),("Mennyi idő alatt kapom meg?","Gyorskérdésnél perceken belül, teljes kutatásnál jellemzően 1–2 napon belül."),("Politikai kérdést is feltehetek?","Igen, közéleti és véleménykérdéseket is — szimulált hangulatképként, nem választási előrejelzésként."),("Mit kapok pontosan?","Online riportot és PDF-et: számok, demográfiai bontás, grafikonok, jellemző indoklások, javaslatok."),("Mennyibe kerül?","A feltüntetett árak példák; a végleges árlista hamarosan."),("Weboldalt is készítetek?","Igen — a kutatás eredményeire építve.")]
def faq2(card): return '<div class="grid md:grid-cols-2 gap-3">'+"".join(f'<details class="{card}"><summary class="cursor-pointer font-semibold">{q}</summary><p class="mt-2 text-sm opacity-80">{a}</p></details>' for q,a in FAQ2)+'</div>'
REP=[("Vásárlási szándék korcsoportonként","pyr"),("Régiók","region"),("Településtípus","settle"),("Megyei hőtérkép","map"),("Árérzékenység","price"),("Kampány előtte/utána","ba"),("Indoklások szófelhője","words"),("Tölcsér","funnel"),("Trendfigyelő: reakció időben","sent"),("Végzettség","edu"),("Jövedelem","inc")]

AV=[("Kata",34,"Győr","könyvelő","derűlátó, de ártérzékeny","😊",68,"#fde68a"),("Laci",58,"Nyíregyháza környéki község","gazdálkodó","aggódó — a rezsi miatt","😟",31,"#bfdbfe"),("Bence",22,"Budapest, XI. ker.","egyetemista","lelkes, trendkövető","🤩",82,"#ddd6fe"),("Erzsi",71,"Kecskemét","nyugdíjas tanár","nyugodt, óvatos költő","🙂",55,"#bbf7d0"),("Gábor",45,"Miskolc","villanyszerelő","fáradt, de bizakodó","😐",47,"#fecaca"),("Nóri",29,"Pécs","grafikus, szabadúszó","kreatív, változékony","😄",73,"#fed7aa")]
def face(i,bg):
  import random;r=random.Random(i);sk=r.choice(["#f4c7a1","#e0ac69","#f1d3b3","#d9a066"]);hr=r.choice(["#2b1b10","#5a3825","#a0703c","#bbb"])
  return f'<svg viewBox="0 0 64 64" class="w-16 h-16 shrink-0"><rect width="64" height="64" rx="16" fill="{bg}"/><circle cx="32" cy="27" r="12" fill="{sk}"/><path d="M20 25a12 12 0 0 1 24 0q-12-8-24 0" fill="{hr}"/><path d="M10 64a22 18 0 0 1 44 0" fill="{r.choice(["#1e3a8a","#9f1239","#065f46","#374151"])}"/></svg>'
def avatars(card,acc):
  cards="".join(f'<div class="{card} flex gap-3">{face(i,bg)}<div class="min-w-0"><p class="font-bold">{n}, {a} <span class="text-xs opacity-60">· #{1000+i*377}</span></p><p class="text-xs opacity-70">{c} · {j}</p><p class="text-sm mt-1">{e} hangulat: <b>{m}</b></p><div class="h-1.5 mt-2 rounded bg-current/20" style="background:rgba(127,127,127,.25)"><div class="h-1.5 rounded mood" data-m="{v}" style="width:{v}%;background:{"#10b981" if v>60 else "#f59e0b" if v>40 else "#f43f5e"}"></div></div></div></div>' for i,(n,a,c,j,m,e,v,bg) in enumerate(AV))
  gauge=f'<div class="{card} text-center"><div class="flex justify-between items-center"><h3 class="font-semibold text-sm">Országos hangulatindex — élő</h3>{MD}</div><svg viewBox="0 0 200 120" class="w-full max-w-xs mx-auto mt-2"><defs><linearGradient id="gg"><stop offset="0" stop-color="#f43f5e"/><stop offset=".5" stop-color="#f59e0b"/><stop offset="1" stop-color="#10b981"/></linearGradient></defs><path d="M20 100a80 80 0 0 1 160 0" fill="none" stroke="url(#gg)" stroke-width="16" stroke-linecap="round"/><g id="needle" style="transform-origin:100px 100px;transition:transform 1.2s"><line x1="100" y1="100" x2="100" y2="34" stroke="currentColor" stroke-width="4" stroke-linecap="round"/></g><circle cx="100" cy="100" r="7" fill="currentColor"/></svg><div class="text-4xl font-bold {acc}"><span id="gv">54</span>/100</div><p class="text-xs opacity-70 mt-1">A 3000 avatar átlagos hangulata. Változik a hírek, az évszak és az árak hatására.</p><div class="grid grid-cols-3 gap-2 mt-3 text-xs">'+"".join(f'<div class="p-2 rounded" style="background:rgba(127,127,127,.12)"><b>{v}</b><br>{l}</div>' for v,l in [("−6","benzinár-hír után"),("+4","tavaszi hónapokban"),("−3","rezsiszámla-hét")])+'</div></div>'
  js='<script>setInterval(()=>{const v=Math.round(48+Math.random()*14);document.getElementById("gv").textContent=v;document.getElementById("needle").style.transform="rotate("+((v-50)*1.8)+"deg)";document.querySelectorAll(".mood").forEach(e=>{const m=Math.max(5,Math.min(95,+e.dataset.m+Math.round(Math.random()*10-5)));e.style.width=m+"%"})},2200)</script>'
  return f'<p class="mb-6 max-w-3xl opacity-80">Minden avatarnak saját élete és <b>saját, változó hangulata</b> van: a hírek, az évszak, az árak és a fizetésnap is hat rá. Együtt az egész országot leképezik — minden megyét, településtípust, korosztályt, jövedelmi és iskolai szintet, életmódot. Az alábbi avatarok rajzolt, szintetikus figurák, nem valós személyek.</p><div class="grid lg:grid-cols-3 gap-4"><div class="lg:col-span-2 grid sm:grid-cols-2 gap-3 content-start">{cards}</div>{gauge}</div><div class="mt-4">'+panel("Hangulat megyénként (100 = legderűsebb)","map",card)+'</div>'+js
def build(n,t,head,navh,herewrap,th,foot):
  card=t["card"];h2=t["h2"]
  o=head+navh+herewrap(hero(t))
  o+=S("avatarok",t["sb"],"Ismerd meg az avatarokat",avatars(card,t["acc"]),h2,"3000 avatar, saját hangulattal — Magyarország kicsiben.")
  o+=S("arak",t["sa"],"Csomagok",tiers(card,t["acc"]),h2,"Válaszd ki, mire van szükséged. Minden ár példa.")
  o+=S("riport",t["sb"],"Mit kapsz? — mintariport",charts(card,REP)+'<div class="mt-6">'+reportpages(card)+'</div>',h2,"Számok, bontások, grafikonok, idézetek és javaslatok. Minden adat Mintaadat.")
  o+=S("kinek",t["sa"],"Kinek való?",uses(card),h2)
  o+=S("utca",t["sb"],"Boltoktól a városházáig",gallery(["zoldseg","sorgyar","bolt","piac","cafe","iroda","debrecen","szeged","eger","sopron","tram","village"],"grid grid-cols-2 md:grid-cols-6 gap-2","h-32"),h2,"Magyar vállalkozások és települések kérdéseire.")
  o+=S("hasonlit",t["sa"],"Hagyományos kutatás vs. magorg.hu",f'<div class="{card}"><div data-chart="cmp"></div></div>',h2)
  o+=S("panel",t["sb"],"A 3000 fős panel — és a korlátai",f'<div class="{card}">{LIM}</div>',h2)
  o+=S("gyik",t["sa"],"Gyakori kérdések",faq2(card),h2)
  o+=f'<section id="kapcsolat" class="{t["cta"]}"><div class="max-w-3xl mx-auto px-5 text-center"><h2 class="{h2}">Tedd fel az első kérdésed még ma.</h2><p class="opacity-80 mt-2">Már 9 900 Ft-tól (példa ár). Gyors, olcsó, szimulált panel.</p><a href="#top" class="inline-block mt-6 {t["btn"]}">Kutatás indítása →</a>'+'<p class="text-xs opacity-60 mt-6">Képek: Wikimedia Commons, szabad licencek — <a class="underline" href="../CREDITS.md">forrásmegjelölés</a>. Minden szám és grafikon <b>mintaadat</b>, az árak <b>példák</b>. Az avatarok szintetikusak, nem valós személyek; az eredmény nem reprezentatív felmérés.</p></div></section>'
  o+=foot+f'<script>const PAL={th.split("p:")[1].split("]")[0]}];</script>'+SC(th)+DEMOJS+'</body></html>'
  o=o.replace('href=#hogyan>Hogyan működik','href=#arak>Csomagok').replace('href=#riport>Mit kapsz','href=#avatarok>Avatarok') if False else o.replace('href=#hogyan>Hogyan működik','href=#arak>Csomagok').replace('href=#panel>Avatar-panel','href=#riport>Mit kapsz').replace('href=#szolg>Szolgáltatások','href=#kinek>Kinek').replace('href=#arak>Árak','href=#panel>Panel')
  page(n,o)
